import { parseYaml, stringifyYaml } from "../../deps/std.js";
import { TransformError } from "./transform-error.js";
export const Yaml = {
    toData(content) {
        try {
            return parseYaml(content);
        }
        catch (error) {
            throw new TransformError(`Malformed YAML code: ${error.message}`);
        }
    },
    fromData(data) {
        return stringifyYaml(data);
    },
};
